    """Parse a version string."""
    match = _VERSION.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid version: {text!r}")
    major, minor, patch, prerelease, build = match.groups()
    return Version(
        int(major),
        int(minor),
        int(patch),
        tuple(prerelease.split(".")) if prerelease else (),
        tuple(build.split(".")) if build else (),
    )


def _version(value: str | Version) -> Version:
    return value if isinstance(value, Version) else parse(value)


def _sign(a, b) -> int:
    return (a > b) - (a < b)


def _compare_identifiers(a: str, b: str) -> int:
    a_numeric, b_numeric = a.isdigit(), b.isdigit()
    if a_numeric and b_numeric:
        return _sign(int(a), int(b))
    if a_numeric or b_numeric:
        return -1 if a_numeric else 1
    return _sign(a, b)


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    a, b = _version(a), _version(b)
    result = _sign((a.major, a.minor, a.patch), (b.major, b.minor, b.patch))
    if result or (not a.prerelease and not b.prerelease):
        return result
    if not a.prerelease or not b.prerelease:
        return 1 if not a.prerelease else -1
    for x, y in zip(a.prerelease, b.prerelease):
        result = _compare_identifiers(x, y)
        if result:
            return result
    return _sign(len(a.prerelease), len(b.prerelease))


def _comparator(text: str) -> tuple[Version, list[tuple[str, Version]]]:
    """A comparator's version and the plain checks it stands for."""
    match = _OPERATOR.match(text)
    operator = match.group() if match else "="
    version = parse(text[match.end():] if match else text)
    if operator == "^":
