from __future__ import annotations

import re

_ALIGNMENTS = ("left", "right", "center", None)
_DELIMITER_CELL = re.compile(r"(:?)-+(:?)")


def _cell(value) -> str:
    return "" if value is None else str(value).replace("|", "\\|")


def _pad(text: str, width: int, align: str | None) -> str:
    space = width - len(text)
    if align == "right":
        return " " * space + text
    if align == "center":
        return " " * (space // 2) + text + " " * (space - space // 2)
    return text + " " * space


def _delimiter(width: int, align: str | None) -> str:
    left = ":" if align in ("left", "center") else "-"
    right = ":" if align in ("right", "center") else "-"
    return left + "-" * (width - 2) + right


def _line(cells: list[str]) -> str:
    return "| " + " | ".join(cells) + " |"


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    columns = len(header)
    if align is None:
        align = [None] * columns
    if len(align) != columns:
        raise ValueError(f"expected {columns} alignments, got {len(align)}")
    for value in align:
        if value not in _ALIGNMENTS:
            raise ValueError(f"invalid alignment: {value!r}")

    table = [[_cell(value) for value in header]]
    for row in rows:
        if len(row) > columns:
            raise ValueError(f"row has {len(row)} cells, header has {columns}")
        table.append([_cell(value) for value in row] + [""] * (columns - len(row)))
    widths = [max(3, *(len(row[i]) for row in table)) for i in range(columns)]

    lines = [_line([_pad(c, w, a) for c, w, a in zip(table[0], widths, align)])]
    lines.append(_line([_delimiter(w, a) for w, a in zip(widths, align)]))
    for row in table[1:]:
        lines.append(_line([_pad(c, w, a) for c, w, a in zip(row, widths, align)]))
    return "\n".join(lines)


def _split(line: str) -> list[str]:
    """Split a table line into stripped, unescaped cells."""
    line = line.strip()
    cells, current, i = [], [], 0
    while i < len(line):
        if line.startswith("\\|", i):
            current.append("|")
            i += 2
            continue
        if line[i] == "|":
            cells.append("".join(current))
            current = []
        else:
            current.append(line[i])
        i += 1
    trailing_pipe = not current and bool(cells)
    if not trailing_pipe:
        cells.append("".join(current))
    if line.startswith("|"):
        cells = cells[1:]
    return [cell.strip() for cell in cells]


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.splitlines()
    while lines and not lines[0].strip():
        lines.pop(0)
    while lines and not lines[-1].strip():
        lines.pop()
    if len(lines) < 2:
        raise ValueError("a table needs a header line and a delimiter line")

    header = _split(lines[0])
    delimiter = _split(lines[1])
    if len(delimiter) != len(header):
        raise ValueError(
            f"delimiter line has {len(delimiter)} cells, header has {len(header)}"
        )
    align = []
    for cell in delimiter:
        match = _DELIMITER_CELL.fullmatch(cell)
        if match is None:
            raise ValueError(f"invalid delimiter cell: {cell!r}")
        left, right = match.groups()
        align.append(
            "center" if left and right
            else "left" if left
            else "right" if right
            else None
        )

    rows = []
    for number, line in enumerate(lines[2:], start=3):
        row = _split(line)
        if len(row) != len(header):
            raise ValueError(
                f"line {number} has {len(row)} cells, header has {len(header)}"
            )
        rows.append(row)
    return header, rows, align

