    """Parse INI text."""
    sections: dict[str, dict[str, str]] = {}
    section = None
    key = None  # the key a continuation line would extend
    for lineno, line in enumerate(_LINE_BREAK.split(text), start=1):
        stripped = line.strip()
        if not stripped or stripped[0] in "#;":
            key = None
            continue
        if key is not None and line[0].isspace():
            section[key] += "\n" + stripped
            continue
        key = None
        if stripped.startswith("[") and stripped.endswith("]"):
            section = sections.setdefault(stripped[1:-1].strip(), {})
            continue
        separator = _KEY_SEPARATOR.search(stripped)
        if separator is None:
            raise ParseError(lineno, f"expected a section or key: {stripped!r}")
        if section is None:
            raise ParseError(lineno, "key before any section")
        name = stripped[: separator.start()].strip().lower()
        if not name:
            raise ParseError(lineno, "empty key")
        section[name] = stripped[separator.end():].strip()
        key = name
    return _interpolate(sections)


def _interpolate(sections: dict[str, dict[str, str]]) -> dict[str, dict[str, str]]:
    resolved: dict[tuple[str, str], str] = {}
    in_progress: set[tuple[str, str]] = set()

    def lookup(section: str, key: str) -> str:
        if section not in sections:
            raise InterpolationError(f"no section {section!r}")
        if key not in sections[section]:
            raise InterpolationError(f"no key {key!r} in section {section!r}")
        ref = (section, key)
        if ref not in resolved:
            if ref in in_progress:
                raise InterpolationError(f"cycle through {section}:{key}")
            in_progress.add(ref)
            resolved[ref] = expand(section, sections[section][key])
            in_progress.discard(ref)
        return resolved[ref]

    def expand(section: str, value: str) -> str:
        out, i = [], 0
        while i < len(value):
            if value.startswith("$$", i):
                out.append("$")
                i += 2
                continue
            if value.startswith("${", i):
                end = value.find("}", i + 2)
                if end != -1:
                    ref = value[i + 2 : end]
                    # Keys can't contain ":", so the last one splits off the section.
                    target, _, key = ref.rpartition(":")
                    target = target.strip() if ":" in ref else section
                    out.append(lookup(target, key.strip().lower()))
                    i = end + 1
                    continue
            out.append(value[i])
            i += 1
        return "".join(out)

    return {
        name: {key: lookup(name, key) for key in keys}
        for name, keys in sections.items()
    }

